// Library, reading queue, study items, goals, and modal composition.

function renderLibrary(){
 const visible=libraryPage.items||[], topics=libraryPage.topics||[];
 const rows=visible.length?visible.map((p,i)=>{const purpose=libraryPaperPurpose(p);return `<div class="library-row"><input class="library-check" type="checkbox" data-library-check="${esc(p.id)}" ${selectedLibraryIds.has(p.id)?'checked':''} aria-label="选择论文"><span class="row-index">${String((libraryPage.offset||0)+i+1).padStart(2,'0')}</span><div class="library-paper-copy"><span class="library-title" data-open-paper="${esc(p.id)}">${esc(p.title)}</span><div class="library-sub">${esc([p.authors,p.doi?`doi:${p.doi}`:'',getTags(p).join(', ')].filter(Boolean).join(' · ')||'作者或标签待补充')} · 阅读卡 ${p.reading_card?.completion_pct||0}%</div><div class="library-purpose"><b>${purpose.source}</b><span>${esc(purpose.text)}</span></div></div><span class="year-cell">${esc(p.year||'—')}</span><span class="venue-cell">${esc(p.venue||p.topic||'—')}</span><button class="fav-button ${p.is_favorite?'on':''}" title="收藏" data-favorite="${esc(p.id)}">${p.is_favorite?'★':'☆'}</button><button class="delete-paper-button" title="删除论文" aria-label="删除论文" data-delete-paper="${esc(p.id)}">×</button></div>`;}).join(''):emptyState(libraryPage.total?'没有匹配的论文':'文献库还空着','可以搜索新论文、导入 Zotero/BibTeX，或把导师推荐的论文添加进来。',libraryPage.total?'':'<button class="button small" data-action="add-paper">添加第一篇</button>');
 const selectedCount=selectedLibraryIds.size;
 const loadMore=libraryPage.has_more?`<div style="display:flex;justify-content:center;padding:16px"><button class="button" data-library-load-more>加载更多 · 已显示 ${visible.length}/${libraryPage.total}</button></div>`:`<div style="text-align:center;padding:14px;color:#99a39d;font-size:9px">已显示 ${visible.length} / ${libraryPage.total} 篇</div>`;
 return `${viewHead('YOUR LIBRARY','文献库','服务器端全文检索、分页加载和长期阅读记录，适合多年积累。',`<button class="button" data-action="import"><span>↧</span> 导入文献</button><button class="button primary" data-action="add-paper"><span class="plus">＋</span> 新增论文</button>`)}<div class="toolbar"><input class="field-input" id="library-filter" value="${esc(libraryQuery)}" placeholder="检索标题、作者、摘要、笔记、阅读卡和 PDF 原文…"><select class="field-select" id="library-status"><option value="">全部阅读状态</option>${STATUS_OPTIONS.map(s=>`<option value="${s}" ${libraryStatus===s?'selected':''}>${STATUS[s]}</option>`).join('')}</select>${topics.length?`<select class="field-select" id="library-topic"><option value="">全部研究主题</option>${topics.map(t=>`<option value="${esc(t)}" ${libraryTopic===t?'selected':''}>${esc(t)}</option>`).join('')}</select>`:''}<select class="field-select" id="library-sort"><option value="recent" ${librarySort==='recent'?'selected':''}>最近更新</option><option value="year_desc" ${librarySort==='year_desc'?'selected':''}>年份最新</option><option value="year_asc" ${librarySort==='year_asc'?'selected':''}>年份最早</option><option value="title" ${librarySort==='title'?'selected':''}>标题</option></select><label class="check-label"><input type="checkbox" id="library-favorite" ${libraryFavorite?'checked':''}> 只看收藏</label><label class="check-label"><input type="checkbox" id="library-has-card" ${libraryHasCard?'checked':''}> 有阅读卡</label><span class="toolbar-spacer"></span><button class="button small" data-export="bibtex">导出 BibTeX</button><button class="button small" data-export="json">导出 JSON</button></div><div class="batch-toolbar"><label class="check-label"><input type="checkbox" data-library-select-all ${visible.length&&visible.every(p=>selectedLibraryIds.has(p.id))?'checked':''}> 全选当前页</label><span>${selectedCount?`已选 ${selectedCount} 篇`:'选择论文后批量分诊'}</span>${selectedCount?`<select class="field-select batch-status"><option value="">批量改状态</option>${STATUS_OPTIONS.map(s=>`<option value="${s}">${STATUS[s]}</option>`).join('')}</select><input class="field-input batch-topic" placeholder="批量设置主题"><button class="button small" data-batch-action="topic">设置主题</button><button class="button small" data-batch-action="favorite">收藏</button><button class="button small" data-batch-action="to_read">加入待读</button><button class="button small" data-batch-action="read">标记已读</button><button class="button small" data-batch-action="excluded">排除</button><button class="button small danger" data-batch-delete>删除选中</button>`:''}</div><div class="list-table"><div class="list-table-head"><span>论文 · ${libraryPage.total} 条记录</span><span>当前页 ${visible.length} 条</span></div>${rows}</div>${loadMore}`;
}

function libraryPaperPurpose(paper={}){
 const card=paper.reading_card||{};
 for(const [field,source] of [['research_question','阅读卡 · 研究问题'],['contribution','阅读卡 · 核心贡献']]){
  const value=String(card[field]||'').trim();if(value)return {source,text:value};
 }
 const abstract=String(paper.abstract||'').replace(/\s+/g,' ').trim();
 if(abstract){const first=abstract.split(/(?<=[.!?。！？])\s+/)[0]||abstract;return {source:'摘要摘录',text:first.length>220?`${first.slice(0,219).trimEnd()}…`:first};}
 return {source:'研究速览',text:'暂无摘要或阅读卡内容，打开记录后可补充。'};
}

const renderLibraryBase = renderLibrary;
renderLibrary = function(){
 const html=renderLibraryBase();
 return html.replace('data-action="import"><span>↧</span> 导入文献</button>', 'data-action="import"><span>↧</span> 导入文献</button><button class="button" data-action="pdf-import"><span>▧</span> 批量导入 PDF</button>');
};

const readingPaperDetailCache=new Map();

async function loadReadingPaperDetail(id,force=false){
 if(!id)return;
 const cached=readingPaperDetailCache.get(id);
 if(cached?.loading||(!force&&cached?.loadedAt&&Date.now()-cached.loadedAt<60000))return;
 readingPaperDetailCache.set(id,{...cached,loading:true,error:''});
 try{
  const data=await api(`/api/papers/${encodeURIComponent(id)}?view=summary`);
  readingPaperDetailCache.set(id,{data,loading:false,error:'',loadedAt:Date.now()});
 }catch(error){
  readingPaperDetailCache.set(id,{...cached,loading:false,error:error.message||'读取失败',loadedAt:Date.now()});
 }
 if(activeView==='reading'&&selectedPaperId===id)renderView();
}

function renderReadingPaperDetails(paper,state={}){
 const sources=Array.isArray(paper.sources)?paper.sources:[];
 const attachments=Array.isArray(paper.attachments)?paper.attachments:[];
 const tags=getTags(paper);
 const fact=(label,value)=>`<div class="reading-record-fact"><dt>${label}</dt><dd>${value||'未登记'}</dd></div>`;
 const sourceRows=sources.length?sources.map(item=>`<div class="reading-record-source"><span>${esc(SOURCE_NAME[item.source]||item.source||'来源')}${item.external_id?` · ${esc(item.external_id)}`:''}</span><small>${item.fetched_at?`收录于 ${esc(fmtDate(item.fetched_at,true))}`:''}</small></div>`).join(''):'<div class="reading-record-source"><span>手动添加</span><small>暂无外部来源记录</small></div>';
 const brief=(paper.ai_artifacts||[]).find(item=>item.artifact_type==='abstract_brief');
 const briefText=brief?.answer||brief?.analysis?.answer||'';
 const modelReady=Boolean(agentConfigured);
 const loading=state.loading?'<span class="reading-record-state">正在补全文献信息…</span>':state.error?`<span class="reading-record-state error">详情补全失败：${esc(state.error)} <button class="text-link" data-reading-detail-retry="${esc(paper.id)}">重试</button></span>`:'';
 const abstract=paper.abstract?`<p class="reading-paper-abstract">${esc(paper.abstract)}</p>`:'<p class="reading-paper-abstract muted">这篇记录没有摘要，可从原文补充或更新元数据。</p>';
 const briefMarkup=briefText?`<div class="reading-brief-answer"><small>最近生成 · ${esc(fmtDate(brief.created_at,true))} · ${esc(brief.model||'模型')} · 仅依据题名、摘要和元数据</small><p>${esc(briefText)}</p></div>`:'<div class="reading-brief-answer empty">还没有摘要助读结果。</div>';
 const doi=paper.doi?`<a href="https://doi.org/${encodeURIComponent(paper.doi)}" target="_blank" rel="noopener">${esc(paper.doi)} ↗</a>`:'';
 const arxiv=paper.arxiv_id?`<a href="https://arxiv.org/abs/${encodeURIComponent(paper.arxiv_id)}" target="_blank" rel="noopener">${esc(paper.arxiv_id)} ↗</a>`:'';
 return `<section class="reader-section reading-record-section reading-anchor" id="reading-info"><div class="reading-record-heading"><div><h4>论文信息与摘要</h4><span>完整文献信息已放在阅读台当前页</span></div>${loading}</div><dl class="reading-record-facts">${fact('DOI',doi)}${fact('arXiv',arxiv)}${fact('研究主题',esc(paper.topic||''))}${fact('标签',esc(tags.join('、')))}</dl><div class="reading-paper-abstract-wrap"><b>摘要</b>${abstract}</div><details class="reading-record-sources"><summary>来源记录 · ${sources.length}</summary>${sourceRows}</details><div class="reading-brief reading-anchor" id="reading-brief-section"><div class="reading-record-heading"><div><h4>摘要助读</h4><span>依据题名、摘要和元数据；发送前需单独确认</span></div></div><div class="ai-job-status reading-brief-status" id="reading-brief-status"></div><div id="agent-result">${briefMarkup}</div><div class="reading-brief-actions"><label class="check-label"><input id="agent-consent" type="checkbox"> 同意将摘要发送到模型服务</label><button class="button small" data-model-required data-source-ready="true" data-agent-brief="${esc(paper.id)}" ${modelReady?'':'disabled'}>生成摘要助读</button></div></div></section>`;
}

function readingPublicPdfUrl(paper={}){
 const isWebUrl=value=>{try{return ['http:','https:'].includes(new URL(value).protocol);}catch{return false;}};
 if(paper.pdf_url&&isWebUrl(paper.pdf_url))return paper.pdf_url;
 const source=String(paper.url||'').trim();
 if(source&&isWebUrl(source)){
  try{
   const url=new URL(source),path=url.pathname.replace(/\/+$/,'').toLowerCase();
   const direct=path.endsWith('.pdf')||path.endsWith('/pdf')||[...url.searchParams].some(([key,value])=>{
    key=key.toLowerCase();value=value.toLowerCase();
    return ['pdf','download'].includes(key)||(['format','type'].includes(key)&&value.includes('pdf'))||value.includes('.pdf');
   });
   if(direct)return source;
   const host=url.hostname.toLowerCase();
   const arxivMatch=host.endsWith('arxiv.org')?url.pathname.match(/^\/(?:abs|pdf|html)\/([^/]+)/i):null;
   if(arxivMatch)return `https://arxiv.org/pdf/${encodeURIComponent(decodeURIComponent(arxivMatch[1]).replace(/\.pdf$/i,'').replace(/v\d+$/i,''))}`;
   if((host.endsWith('biorxiv.org')||host.endsWith('medrxiv.org'))&&url.pathname.startsWith('/content/'))return `${url.origin}${url.pathname.replace(/\/+$/,'')}.full.pdf`;
  }catch{}
 }
 let arxivId=String(paper.arxiv_id||'').trim();
 if(!arxivId&&String(paper.doi||'').toLowerCase().startsWith('10.48550/arxiv.'))arxivId=String(paper.doi).slice('10.48550/arxiv.'.length);
 if(arxivId)return `https://arxiv.org/pdf/${encodeURIComponent(arxivId.replace(/^https?:\/\/(www\.)?arxiv\.org\/(abs|pdf|html)\//i,'').replace(/\.pdf$/i,''))}`;
 if(String(paper.doi||'').toLowerCase().startsWith('10.64898/'))return `https://www.biorxiv.org/content/${encodeURIComponent(paper.doi).replace(/%2F/gi,'/')}.full.pdf`;
 return '';
}

function renderReading(){
 const readingList=papers.filter(p=>['reading','to_read','inbox','later'].includes(p.status)).sort((a,b)=>{const rank=s=>s==='reading'?0:s==='to_read'?1:s==='inbox'?2:3;return rank(a.status)-rank(b.status);});
 const selected=readingList.find(p=>p.id===selectedPaperId)||readingList.find(p=>p.status==='reading')||readingList[0];
 selectedPaperId=selected?.id||'';
 const list=readingList.length?readingList.map(p=>`<button class="reading-select ${selected?.id===p.id?'active':''}" data-select-paper="${p.id}"><b>${esc(p.title)}</b><small>${esc([p.year,STATUS[p.status]].filter(Boolean).join(' · '))}</small></button>`).join(''):emptyState('暂时没有待读论文','从文献库或发现页把论文加入待读清单。');
 const flow=`<div class="reader-flow" aria-label="论文阅读流程"><div class="reader-flow-title"><b>一篇论文的长期阅读路径</b><span>每一步都单独保存，随时退出后继续</span></div><div class="reader-flow-steps"><span><i>1</i>读前准备</span><span><i>2</i>阅读卡</span><span><i>3</i>全文精读</span><span><i>4</i>复习与行动</span></div></div>`;
 if(!selected)return `${viewHead('READING DESK','阅读台','从摘要和笔记开始，逐步沉淀成可核验的论文理解。')}${flow}<div class="surface-card">${list}</div>`;
 const detailState=readingPaperDetailCache.get(selected.id)||{};
 const paper={...selected,...(detailState.data||{}),status:selected.status,notes:selected.notes,reading_card:selected.reading_card||detailState.data?.reading_card};
 const attachments=paper.attachments||[];
 const purpose=typeof libraryPaperPurpose==='function'?libraryPaperPurpose(paper):null;
 const nav=[['reading-info','论文信息'],['reading-brief-section','摘要助读'],['reading-card-section','阅读卡'],['reading-analysis-section','全文精读'],['reading-notes','我的笔记'],['reading-attachments','PDF 附件']];
 const sectionNav=`<nav class="reading-section-nav" aria-label="阅读台分类">${nav.map(([id,label],index)=>`<button type="button" class="button small ${index===0?'active':''}" data-reading-section="${id}">${label}</button>`).join('')}</nav>`;
 const localPdf=attachments[0];
 const pdfAction=localPdf?`<a class="button small" href="/files/${esc(localPdf.stored_name)}" target="_blank" rel="noopener">打开本地 PDF ↗</a>`:`<button class="button small" data-download-pdf="${esc(paper.id)}">查找并下载 PDF</button>`;
 const publicPdf=readingPublicPdfUrl(paper);
 const analysisMarkup=typeof renderReadingAnalysisPanel==='function'?renderReadingAnalysisPanel(paper,readingAnalysisCache.get(paper.id)||{}):'';
 return `${viewHead('READING DESK','阅读台','论文信息、摘要助读、阅读卡和全文分析都在当前页持续阅读。')}${flow}<div class="reading-layout"><aside class="surface-card reading-list-card"><h4>阅读队列 <span style="color:#a0aaa3;font-weight:400">${readingList.length}</span></h4>${list}</aside><section class="surface-card reader-card"><div class="reader-topline"><span>READING NOTE · ${esc(STATUS[paper.status])}</span><span>${paper.year||'年份待确认'}</span></div><h2 class="reader-title">${esc(paper.title)}</h2><div class="reader-authors">${esc(paper.authors||'作者信息待补充')}${paper.venue?` · ${esc(paper.venue)}`:''}</div>${purpose?`<div class="reading-purpose"><b>${esc(purpose.source)}</b><span>${esc(purpose.text)}</span></div>`:''}<div class="reader-controls"><select class="field-select" style="width:125px;height:30px" data-paper-status="${paper.id}">${STATUS_OPTIONS.map(s=>`<option value="${s}" ${paper.status===s?'selected':''}>${STATUS[s]}</option>`).join('')}</select><button type="button" class="fav-button reader-favorite ${paper.is_favorite?'on':''}" data-favorite="${esc(paper.id)}" aria-label="${paper.is_favorite?'取消收藏':'收藏论文'}" title="${paper.is_favorite?'取消收藏':'收藏论文'}">${paper.is_favorite?'★':'☆'}</button>${paper.url?`<a class="button small" href="${esc(paper.url)}" target="_blank" rel="noopener">打开来源 ↗</a>`:''}${publicPdf?`<a class="button small" href="${esc(publicPdf)}" target="_blank" rel="noopener">打开公开 PDF ↗</a>`:''}${pdfAction}<button class="button small primary" data-enter-deepread="${paper.id}">逐段对照 PDF</button><label class="button small" style="cursor:pointer">添加 PDF<input type="file" accept="application/pdf,.pdf" data-attach-paper="${paper.id}" hidden></label></div>${sectionNav}${renderReadingPaperDetails(paper,detailState)}<div class="reading-card-slot"></div>${analysisMarkup}<div class="reader-section reading-notes-section reading-anchor" id="reading-notes"><h4>我的阅读笔记</h4><textarea class="reader-note" id="reader-note" data-note-paper="${paper.id}" placeholder="研究问题是什么？方法和证据是什么？哪些结论需要我回到原文核验？\n\n建议按：问题 / 方法 / 数据与基线 / 结果 / 局限 / 对我课题的启发 来记录。">${esc(paper.notes||'')}</textarea><div class="reading-note-actions"><span>笔记与阅读卡会保存在文献库</span><button class="button small primary" data-save-note="${paper.id}">保存笔记</button></div></div><div class="reader-section reading-attachments-section reading-anchor" id="reading-attachments"><h4>本地 PDF 附件</h4>${attachments.length?attachments.map(a=>`<a class="file-chip" href="/files/${esc(a.stored_name)}" target="_blank" rel="noopener">▧ ${esc(a.original_name)} · ${Math.max(1,Math.round(a.byte_size/1024))} KB</a>`).join(' '):`<p class="reading-paper-muted">尚未添加 PDF。可用上方自动查找或上传文件，之后能建立逐段对照。</p>`}</div></section></div>`;
}

function studyReviewDate(value){if(!value)return '';const date=new Date(value);return Number.isNaN(date.getTime())?'':date.toLocaleDateString('zh-CN',{year:'numeric',month:'short',day:'numeric'});}
function renderPrereading(){
 const counts=studyPage.counts||{},byType=studyPage.by_type||{},review=studyPage.review||{},readiness=studyPage.readiness||{};
 const kindLabel={prerequisite:'先修基础',glossary:'专业术语',notation:'公式与符号',self_check:'自测题'};
 const basisLabel=item=>item.item_type==='self_check'?'检验是否会讲':item.item_type==='prerequisite'?(item.necessity==='required'&&item.basis==='paper'?'本文明确依赖':item.basis==='inferred'?'AI 建议补充':'建议掌握'):item.basis==='paper'?'本文原文依据':item.basis==='background'?'背景释义':'待回原文核验';
 const items=studyPage.items||[],ratingLabels={again:'忘了',hard:'困难',good:'记住',easy:'轻松'};
 const itemRow=item=>`<article class="study-item-row"><div class="study-item-copy"><div class="study-item-meta"><span class="study-kind">${kindLabel[item.item_type]||'读前知识'}</span><button class="study-paper-link" data-open-paper="${esc(item.paper_id)}">${esc(item.paper_title||'未命名论文')}${item.year?` · ${esc(item.year)}`:''}</button><span class="study-review-tag ${item.review_due?'due':''}">${item.review_due?'到期复习':item.review_due_at?`下次复习 ${studyReviewDate(item.review_due_at)}`:item.mastery==='mastered'?'已掌握':'待复习'}</span></div><div class="study-item-title">${esc(item.label)}${item.expansion?` <small>${esc(item.expansion)}</small>`:''}<span class="prereading-tag">${basisLabel(item)}</span></div><p>${esc(item.explanation||'')}</p>${item.paper_role?`<small class="study-item-role">本文中的作用：${esc(item.paper_role)}</small>`:''}${item.review_due&&studyDueOnly?`<div class="study-review-actions"><span>自评</span>${Object.entries(ratingLabels).map(([rating,label])=>`<button type="button" class="button small" data-study-review="${esc(item.id)}" data-review-rating="${rating}">${label}</button>`).join('')}<small>连续记住 ${Number(item.review_count||0)} 次 · 上次 ${studyReviewDate(item.last_reviewed_at)||'首次复习'}</small></div>`:''}${item.quote?`<blockquote class="study-item-evidence">${esc(item.quote)}${item.pdf_url?` <a href="${esc(item.pdf_url)}" target="_blank" rel="noopener">第 ${esc(item.page_number)} 页 ↗</a>`:` <span>第 ${esc(item.page_number)} 页</span>`}</blockquote>`:''}<details class="study-item-note"><summary>${item.user_note?'查看 / 修改我的理解':'补充我的理解'}</summary><textarea maxlength="2000" data-study-note="${esc(item.id)}" placeholder="用自己的话解释它，或记下读论文时遇到的问题。">${esc(item.user_note||'')}</textarea><button class="button small" data-save-study-note="${esc(item.id)}">保存</button></details></div><div class="study-item-actions"><select class="field-select" data-study-status="${esc(item.id)}" aria-label="学习状态"><option value="new" ${item.mastery==='new'?'selected':''}>待学</option><option value="learning" ${item.mastery==='learning'?'selected':''}>学习中</option><option value="mastered" ${item.mastery==='mastered'?'selected':''}>已掌握</option></select><button class="icon-button study-remove" data-study-delete="${esc(item.id)}" title="移除此条读前知识" aria-label="移除此条读前知识">×</button></div></article>`;
 const groupDefinitions=[['prerequisite','一、这篇论文必须先懂','不懂这些概念会直接卡住方法或实验理解。'],['glossary','二、论文专业术语','先用本文语境理解，再考虑领域里的其他含义。'],['notation','三、公式、符号与指标','只保留本文实际出现、读公式和结果表必须用到的内容。'],['self_check','四、读前自测','先尝试自己回答，再展开答案要点；答不出就回到对应知识组。']];
 const rows=items.length?groupDefinitions.map(([type,title,help])=>{const group=items.filter(item=>item.item_type===type);return group.length?`<section class="study-knowledge-group"><div class="study-knowledge-group-head"><div><h3>${title}</h3><p>${help}</p></div><span>${group.length} 项</span></div>${group.map(itemRow).join('')}</section>`:''}).join(''):studyDueOnly?'<div class="empty-state">今天的复习已完成。 <button class="button small" type="button" data-study-due-toggle>返回全部知识</button></div>':emptyState('还没有读前知识','在论文详情中生成读前准备后，这里会按论文和知识类型建立清晰的学习清单。','<button class="button small" data-nav="library">打开文献库</button>');
 const next=readiness.next_item;
 const readinessText=readiness.total_items?`已掌握 ${readiness.mastered_items||0}/${readiness.total_items} 条 · ${readiness.required_items?`明确必需 ${readiness.required_mastered||0}/${readiness.required_items} 条`:'当前没有论文明确标为必需的先修项'}`:'生成读前准备后会自动建立学习清单';
 const reviewSession=studyDueOnly||review.due_count?`<section class="study-review-session"><div><b>${studyDueOnly?'到期复习':`今日待复习 ${review.due_count}`}</b><span>${studyDueOnly?`剩余 ${studyPage.total||0} 条 · 逾期 ${review.overdue_count||0} 条`:`${review.overdue_count||0} 条逾期`}</span></div><button class="button small ${studyDueOnly?'':'primary'}" type="button" data-study-due-toggle>${studyDueOnly?'返回全部知识':'开始复习'}</button></section>`:'';
 const knowledgeMap=`<section class="study-knowledge-map"><div><b>每篇论文独立建立读前路线</b><span>先选一篇论文，再按“必须先懂 → 术语 → 公式指标 → 自测”顺序学习。背景知识与本文证据分开标注。</span></div><div class="study-knowledge-steps"><span><i>1</i><b>先修基础</b><small>为什么必须懂</small></span><span><i>2</i><b>专业术语</b><small>本文怎么使用</small></span><span><i>3</i><b>公式指标</b><small>变量如何对应</small></span><span><i>4</i><b>自测复习</b><small>能否讲给别人</small></span></div></section>`;
 const options=Array.isArray(studyPage.paper_options)?studyPage.paper_options:[],paperSelect=`<section class="study-paper-focus"><div><small>当前学习对象</small><b>${studyPaperId?esc(options.find(item=>item.id===studyPaperId)?.title||'当前论文'):'全部论文'}</b><span>${studyPaperId?'下面只展示这篇论文的专属读前知识。':'选择论文后，知识会按本文的路线和分类展开。'}</span></div><select class="field-select" id="study-paper"><option value="">全部论文</option>${options.map(item=>`<option value="${esc(item.id)}" ${studyPaperId===item.id?'selected':''}>${esc(item.title)} · ${Number(item.item_count||0)} 条</option>`).join('')}</select></section>`;
 return `${viewHead('BEFORE YOU READ','读前知识','每篇论文都有自己的最短学习路线；先解决“读这篇论文必须懂什么”，再进入精读。',`<button class="button" data-nav="reading">去阅读台</button>`)}${paperSelect}${knowledgeMap}<div class="study-readiness"><div class="study-readiness-score"><small>读前掌握度${studyPaperId?' · 当前论文':''}</small><b>${readiness.percent||0}%</b><span>${readinessText}</span></div><div class="study-readiness-next"><small>建议下一项</small><b>${next?esc(next.label):'暂无待学条目'}</b><span>${next?`${esc(kindLabel[next.item_type]||'读前知识')} · ${esc(next.paper_title||'')}`:'所有已生成内容都已掌握'}</span></div></div>${reviewSession}<div class="study-summary"><div><b>${counts.new||0}</b><span>待学</span></div><div><b>${counts.learning||0}</b><span>学习中</span></div><div><b>${counts.mastered||0}</b><span>已掌握</span></div><div class="study-summary-types"><span>${byType.prerequisite||0} 个先修概念</span><span>${byType.glossary||0} 个专业术语</span><span>${byType.notation||0} 个公式符号</span><span>${byType.self_check||0} 道自测</span></div></div><div class="toolbar study-toolbar"><input class="field-input" id="study-filter" value="${esc(studyQuery)}" placeholder="在当前论文中搜索概念、术语或释义…"><select class="field-select" id="study-mastery"><option value="" ${studyMastery===''?'selected':''}>全部掌握状态</option><option value="new" ${studyMastery==='new'?'selected':''}>待学</option><option value="learning" ${studyMastery==='learning'?'selected':''}>学习中</option><option value="mastered" ${studyMastery==='mastered'?'selected':''}>已掌握</option></select><select class="field-select" id="study-type"><option value="" ${studyType===''?'selected':''}>全部知识类型</option><option value="prerequisite" ${studyType==='prerequisite'?'selected':''}>先修基础</option><option value="glossary" ${studyType==='glossary'?'selected':''}>专业术语</option><option value="notation" ${studyType==='notation'?'selected':''}>公式与符号</option><option value="self_check" ${studyType==='self_check'?'selected':''}>读前自测</option></select><span class="toolbar-spacer"></span><span class="study-result-count">${studyPage.total||0} 条</span></div><div class="study-item-list">${rows}</div>${studyPage.has_more?`<div class="study-load-more"><button class="button" data-study-load-more>加载更多 · 已显示 ${items.length}/${studyPage.total}</button></div>`:''}`;
}

function renderAnalytics(){
 if(!analytics){api('/api/analytics').then(data=>{analytics=data;renderView();}).catch(e=>toast(e.message,'error'));return `${viewHead('RESEARCH ANALYTICS','数据分析','把阅读与检索变成可观察、可优化的研究流程。')}<div class="surface-card empty-state"><span class="spinner"></span><p style="margin:10px 0 0">正在计算本地指标…</p></div>`;}
 const m=analytics.metrics||{};const weekly=analytics.weekly||[];const peak=Math.max(1,...weekly.map(w=>Math.max(w.added||0,w.read||0)));const fmt=n=>new Intl.NumberFormat('zh-CN').format(n||0);const sourceRows=(analytics.source_health||[]).length?(analytics.source_health||[]).map(s=>`<div class="source-line"><span>${esc(SOURCE_NAME[s.source]||s.source)}</span><span>成功 ${s.success}/${s.runs} · 原始 ${fmt(s.fetched)} · 候选 ${fmt(s.accepted)} · 过滤 ${fmt(s.filtered)}</span></div>`).join(''):'<div class="empty-state" style="padding:15px">还没有来源运行数据</div>';const topicRows=(analytics.topics||[]).map(t=>`<div style="display:flex;align-items:center;gap:10px;padding:8px 0;border-bottom:1px solid #eff2ef"><span style="width:90px;font-size:9px;color:#6b786f;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(t.topic)}</span><div style="height:7px;background:#edf1ed;border-radius:6px;flex:1;overflow:hidden"><i style="display:block;width:${Math.min(100,Math.round((t.n/Math.max(1,analytics.topics[0]?.n||1))*100))}%;height:100%;background:#7b9d82;border-radius:6px"></i></div><span style="font-size:9px;color:#91a097">${fmt(t.n)}</span></div>`).join('')||'<div class="empty-state" style="padding:15px">给论文添加主题后，这里会出现研究方向分布</div>';
 const bars=weekly.map(w=>`<div style="display:flex;flex-direction:column;align-items:center;gap:5px;flex:1;min-width:24px"><div style="height:110px;display:flex;align-items:flex-end;gap:3px"><i title="新增 ${w.added}" style="display:block;width:7px;height:${Math.max(3,Math.round((w.added/peak)*100))}px;background:#7b9d82;border-radius:3px 3px 0 0"></i><i title="读完 ${w.read}" style="display:block;width:7px;height:${Math.max(3,Math.round((w.read/peak)*100))}px;background:#d1a36b;border-radius:3px 3px 0 0"></i></div><span style="font-size:8px;color:#9ca69f">${esc(w.week.slice(5))}</span></div>`).join('');
 const metricCards=[
  ['馆藏论文',fmt(m.total_papers)],['待读积压',fmt(m.backlog)],['正在阅读',fmt(m.reading)],['近 30 天读完',fmt(m.read_30d)],
  ['近 30 天新增',fmt(m.new_30d)],['检索成功率',`${fmt(m.success_rate)}%`],['候选去重率',`${fmt(m.dedup_rate)}%`],['阅读卡覆盖率',`${fmt(m.reading_card_coverage)}%`],
 ].map(([label,value])=>`<div><small>${label}</small><b>${value}</b></div>`).join('');
 const chartContent=bars||'<div class="empty-state" style="padding:20px">还没有周度活动记录</div>';
 const sourceSummary=analytics.source_health?.length?`共 ${analytics.source_health.length} 个来源 · ${fmt(m.runs_30d)} 次主题同步`:'主题检索开始运行后会显示来源成功率与筛选情况';
 return `${viewHead('RESEARCH ANALYTICS','数据分析','观察阅读进度、检索表现和研究资料沉淀。',`<button class="button" data-action="refresh-analytics">刷新指标</button>`)}
  <div class="analytics-metric-grid">${metricCards}</div>
  <div class="analytics-dashboard-grid">
   <section class="analytics-section"><div class="section-heading"><div><h2>近 12 周活动</h2><p>每周新增与读完论文数量</p></div><span class="evaluation-status">峰值 ${fmt(peak)} 篇</span></div><div class="analytics-chart">${chartContent}</div><div class="analytics-legend"><span><i class="analytics-legend-added"></i>新增</span><span><i class="analytics-legend-read"></i>读完</span></div></section>
   <section class="analytics-section"><div class="section-heading"><div><h2>研究主题</h2><p>按馆藏记录统计</p></div></div><div class="analytics-topic-list">${topicRows}</div></section>
  </div>
  <section class="analytics-section analytics-sources"><div class="section-heading"><div><h2>来源运行情况</h2><p>${sourceSummary}</p></div></div><div class="settings-list">${sourceRows}</div></section>`;
 }

 function renderSettings(){
 if(!settingsSnapshot){
    Promise.all([api('/api/settings/model'),api('/api/health'),api('/api/metrics'),api('/api/diagnostics'),api('/api/maintenance/status'),api('/api/settings/backup-policy'),api('/api/ai-jobs?limit=30'),api('/api/sync-jobs?limit=30')]).then(([model,health,metrics,diagnostics,maintenance,backupPolicy,aiJobData,syncData])=>{settingsSnapshot={model,health,metrics,diagnostics,maintenance,backupPolicy,aiJobs:aiJobData.jobs||[],syncJobs:syncData||[]};aiJobs=aiJobData.jobs||[];syncJobs=syncData||[];applyModelConfiguration(model);scheduleGlobalAiJobsRefresh();renderView();}).catch(e=>{modelConfigState={...modelConfigState,status:'error',error:e.message||'模型配置读取失败'};updateModelDependentControls();toast(`设置读取失败：${e.message}`,'error');scheduleModelConfigurationRefresh();});
    return `${viewHead('SYSTEM SETTINGS','系统设置','集中管理 OpenAI 兼容模型、运行边界和本地数据服务状态。',`<button class="button primary" data-action="agent-config">打开模型配置</button><button class="button" data-action="refresh-settings">刷新状态</button>`)}<div class="surface-card empty-state"><span class="spinner"></span><p style="margin:10px 0 0">正在读取系统配置…</p></div>`;
 }
 const model=settingsSnapshot.model||{}, health=settingsSnapshot.health||{}, metrics=settingsSnapshot.metrics||{}, diagnostics=settingsSnapshot.diagnostics||{}, modelUsage=metrics.model_usage||{};
 const modelState=model.api_key_set&&model.enabled?'已启用':model.api_key_set?'已配置但未启用':'未配置 API Key';
 const healthState=health.ready?'正常':'需要检查';
 const jobs=settingsSnapshot.aiJobs||[], sync=settingsSnapshot.syncJobs||[];const jobRows=[...jobs.map(job=>({...job,_kind:'ai'})),...sync.map(job=>({...job,_kind:'sync'}))].sort((a,b)=>String(b.updated_at||'').localeCompare(String(a.updated_at||''))).slice(0,20);const jobRowsMarkup=jobRows.length?jobRows.map(job=>{if(job._kind==='sync'){const status=job.status==='success'?'已完成':job.status==='running'?'运行中':job.status==='interrupted'?'上次运行中断':job.status==='retryable'?'等待重试':job.status==='partial'?'部分完成':job.status==='failed'?'失败':job.status;const current=Number(job.progress_current||0),total=Number(job.progress_total||0),progress=total?` · 来源 ${current}/${total}`:'';const source=job.current_source?` · ${SOURCE_NAME[job.current_source]||job.current_source}`:'';const retryable=['failed','partial','interrupted','retryable'].includes(job.status);return `<div class="source-line"><span><b>文献检索 · ${esc(status)}</b><small style="display:block;color:#9aa59d;margin-top:3px">${esc(job.query_name||job.query_id||'研究主题')} · ${esc(job.stage||'')}${progress}${source}${job.last_error||job.run_error?` · ${esc(job.last_error||job.run_error)}`:''}</small></span><span>${job.status==='running'?'进行中':job.duration_ms?`${Math.round(Number(job.duration_ms)/1000)} 秒`:job.updated_at?esc(fmtDate(job.updated_at,true)):''}${retryable?` <button class="button small" data-discovery-history-rerun="${esc(job.run_id||'')}">重试</button>`:''}</span></div>`;}const total=Number(job.progress_total||0),current=Number(job.progress_current||0),pct=total?Math.round(current/total*100):job.status==='success'?100:0;const retryable=['failed','partial','interrupted','cancelled'].includes(job.status);return `<div class="source-line"><span><b>${esc(aiJobLabel(job))}</b> · ${esc(job.paper_title||job.paper_id)}<small style="display:block;color:#9aa59d;margin-top:3px">${esc(job.message||'')} ${job.error?` · ${esc(job.error)}`:''}</small></span><span>${esc(aiJobStatusText(job))}${total?` · ${current}/${total} (${pct}%)`:''}${retryable?` <button class="button small" data-retry-ai-job="${esc(job.id)}">重试</button>`:''}</span></div>`;}).join(''):'<div class="empty-state" style="padding:12px">还没有后台任务</div>';const modelTaskName={fast:'快速任务',analysis:'论文分析',vision:'多模态视觉',embedding:'语义索引',connection_test:'连接测试'};const modelUsageRows=(modelUsage.by_task||[]).map(item=>`<div class="source-line"><span>${esc(modelTaskName[item.task]||item.task)}</span><span>${Number(item.calls||0)} 次 · ${Number(item.failures||0)} 次失败 · ${Number(item.total_tokens||0).toLocaleString('zh-CN')} tokens · p95 ${Number(item.max_latency_ms||0).toLocaleString('zh-CN')} ms</span></div>`).join('')||'<div class="empty-state" style="padding:10px">当前统计窗口还没有记录模型调用</div>';
  return `${viewHead('SYSTEM SETTINGS','系统设置','集中管理模型连接、运行边界、本地数据和长期任务状态。',`<button class="button primary" data-action="agent-config">打开模型配置</button><button class="button" data-action="refresh-settings">刷新状态</button>`)}<div class="settings-grid"><section class="surface-card settings-card"><div class="section-heading" style="margin:0 0 10px"><div><h3>模型连接</h3><p>支持任意 OpenAI 兼容中转或自建服务，密钥不会回显。</p></div><span class="evaluation-status">${modelState}</span></div><div class="settings-list"><div><span>供应商</span><b>${esc(model.provider||'未设置')}</b></div><div><span>官网链接</span><b>${esc(model.website_url||'未设置')}</b></div><div><span>Base URL</span><b>${esc(model.base_url||'未设置')}</b></div><div><span>API 请求地址</span><b>${esc(model.api_url||'按 Base URL 推导')}</b></div><div><span>模型 / 协议</span><b>${esc(model.model||'未设置')} · ${model.protocol==='responses'?'Responses':'Chat Completions'}</b></div><div><span>API Key</span><b>${model.api_key_set?`已配置（${esc(model.api_key_source||'未知来源')}）`:'未配置'}</b></div></div><div class="evaluation-note">修改官网、Base URL、完整 API 请求地址、模型或 Key，请点击“打开模型配置”。本地密钥文件会在服务更新后继续保留。</div></section><section class="surface-card settings-card"><div class="section-heading" style="margin:0 0 10px"><div><h3>本地服务状态</h3><p>用于确认刷新后任务和数据是否仍由本机服务接管。</p></div><span class="evaluation-status">${healthState}</span></div><div class="settings-list"><div><span>服务版本</span><b>${esc(health.app_version||'')}</b></div><div><span>数据库</span><b>${esc(typeof health.database==='object'?'SQLite · '+(health.database.status||'ok'):'本机 SQLite')}</b></div><div><span>后台调度器</span><b>${health.scheduler?.status==='ok'?'运行中':'未运行'}</b></div><div><span>运行时请求</span><b>${metrics.requests_total||0} 次 · 错误率 ${metrics.error_rate_pct||0}%</b></div><div><span>最近请求</span><b>${esc(metrics.last_request_at||'暂无')}</b></div><div><span>数据目录</span><b>${esc(appState?.data_dir||'本机数据目录')}</b></div></div></section></div><section class="surface-card decision-card"><div class="section-heading" style="margin:0 0 10px"><div><h3>AI 与检索任务中心</h3><p>刷新页面后仍可查看正在运行、已完成、失败和服务重启中断的任务。</p></div><span class="evaluation-status">${jobRows.filter(job=>job.status==='running'||job.status==='queued').length} 个运行中</span></div>${jobRowsMarkup}</section><section class="surface-card decision-card"><h3>长期任务记录</h3><p>全文阅读卡、AI 精读和文献检索都会先进入可恢复任务记录。刷新或重新打开论文时，系统会读取任务阶段、进度、耗时和错误；服务重启导致未完成的任务会明确标记为“已中断”。</p><div class="decision-tags"><span>任务状态持久化</span><span>进度按内容块记录</span><span>失败原因可追溯</span></div></section>`;
}

function maintenancePanel(data={}){const c=data.counts||{}, db=data.database||{}, index=data.index||{}, orphans=data.orphans||{};const mib=n=>`${(Number(n||0)/1048576).toFixed(1)} MB`;return `<section class="surface-card settings-card" style="margin-top:14px"><div class="section-heading" style="margin:0 0 12px"><div><h3>本地资料维护</h3><p>索引是可重建的派生数据；重建不会改动论文、阅读记录或附件。</p></div><button class="button small" data-action="rebuild-search-index">重建全文索引</button></div><div class="evaluation-grid"><div><small>全文索引</small><b>${index.documents_match_papers&&index.page_documents_match_pages?'完整':'需检查'} · ${esc(index.search_backend||(index.fts5?'FTS5':'字段降级'))}</b></div><div><small>论文 / 索引文档</small><b>${c.papers||0} / ${c.search_documents||0}</b></div><div><small>PDF 页 / 页索引</small><b>${c.pages||0} / ${c.page_search_documents||0}</b></div><div><small>历史快照</small><b>${c.revisions||0}</b></div><div><small>本机数据库</small><b>${mib(db.bytes)}${Number(db.wal_bytes)?` · WAL ${mib(db.wal_bytes)}`:''}</b></div></div><div class="evaluation-note">PDF 附件 ${c.attachments||0} 个 · 孤儿附件 ${orphans.attachments||0} · 孤儿页文本 ${orphans.pages||0} · schema ${esc(db.schema_version||'')}</div></section>`;}
function backupSettingsPanel(policy={}){const maintenance=settingsSnapshot?.maintenance||{}, backups=maintenance.backups||{};return `<section class="surface-card settings-card" style="margin-top:14px"><div class="section-heading" style="margin:0 0 12px"><div><h3>自动备份</h3><p>应用运行期间定时创建可恢复的数据库与 PDF 归档。</p></div><span class="evaluation-status">${policy.enabled?'已启用':'已暂停'}</span></div><div class="toolbar"><label class="check-label"><input id="backup-enabled" type="checkbox" ${policy.enabled?'checked':''}> 启用自动备份</label><label>间隔（小时） <input class="field-input" id="backup-interval" type="number" min="1" max="8760" value="${Number(policy.interval_hours||24)}" style="width:100px"></label><label>保留（份） <input class="field-input" id="backup-retention" type="number" min="1" max="365" value="${Number(policy.retention||14)}" style="width:90px"></label><button class="button small primary" data-action="save-backup-policy">保存设置</button></div><div class="evaluation-grid"><div><small>归档数量</small><b>${backups.count||0}</b></div><div><small>最近成功</small><b>${policy.last_success_at?fmtDate(policy.last_success_at,true):'尚未自动备份'}</b></div><div><small>下次计划</small><b>${policy.enabled&&policy.next_run_at?fmtDate(policy.next_run_at,true):policy.enabled?'启动后执行':'已暂停'}</b></div><div><small>手动归档</small><b>不受自动轮换影响</b></div></div>${policy.last_error?`<div class="evaluation-note" style="color:#b75a53">最近一次自动备份失败：${esc(policy.last_error)}</div>`:`<div class="evaluation-note">自动归档保留最近设置数量；更早的自动归档会轮换清理，手动创建的备份不会被清理。</div>`}</section>`;}
function workspaceMembersPanel(){
 const roleNames={owner:'所有者',admin:'管理员',researcher:'研究者',reviewer:'评审者',viewer:'只读'};
 const rows=workspaceMembers.map(member=>{const owner=member.role==='owner';return `<div class="member-row" data-member-row="${esc(member.id)}"><div class="member-identity"><b>${esc(member.display_name||member.username)}</b><small>${esc(member.username)} · ${roleNames[member.role]||member.role}</small></div>${owner?'<span class="evaluation-status">所有者</span>':`<select class="field-select" data-member-role aria-label="成员角色"><option value="admin" ${member.role==='admin'?'selected':''}>管理员</option><option value="researcher" ${member.role==='researcher'?'selected':''}>研究者</option><option value="reviewer" ${member.role==='reviewer'?'selected':''}>评审者</option><option value="viewer" ${member.role==='viewer'?'selected':''}>只读</option></select><label class="check-label"><input type="checkbox" data-member-active ${member.active?'checked':''}> 可登录</label><button class="button small" data-save-member="${esc(member.id)}">保存</button>`}</div>`;}).join('');
 return `<section class="surface-card settings-card team-members-panel"><div class="section-heading" style="margin:0 0 12px"><div><h3>团队成员</h3><p>当前为单个共享工作区；成员共享文献库和任务，角色限制可执行的操作。</p></div><button class="button small" data-action="auth-password">修改我的密码</button></div><div class="team-member-list">${rows||'<div class="empty-state">暂无成员</div>'}</div><form id="workspace-member-form" class="member-create-form"><label>显示名称<input class="field-input" name="display_name" maxlength="120" placeholder="可选"></label><label>用户名<input class="field-input" name="username" required minlength="3" maxlength="40" pattern="[A-Za-z0-9][A-Za-z0-9._-]{2,39}"></label><label>初始密码<input class="field-input" name="password" type="password" required minlength="12" maxlength="256" autocomplete="new-password"></label><label>角色<select class="field-select" name="role"><option value="researcher">研究者</option><option value="reviewer">评审者</option><option value="viewer">只读</option><option value="admin">管理员</option></select></label><button class="button small primary" type="submit">创建成员</button></form><small class="auth-hint">初始密码至少 12 位，并同时包含字母与数字。工作区资料保存在当前服务器的数据目录。</small></section>`;
}
const renderWithMaintenance=renderView;
function modelUsagePanel(data={}){const taskName={fast:'快速任务',analysis:'论文分析',vision:'多模态视觉',embedding:'语义索引',connection_test:'连接测试',model_web:'联网检索'};const rows=(data.by_task||[]).map(item=>`<div class="source-line"><span>${esc(taskName[item.task]||item.task)}</span><span>${Number(item.calls||0)} 次 · 失败 ${Number(item.failures||0)} · ${Number(item.total_tokens||0).toLocaleString('zh-CN')} tokens · 均值 ${Number(item.mean_latency_ms||0).toLocaleString('zh-CN')} ms</span></div>`).join('')||'<div class="empty-state" style="padding:10px">当前统计窗口还没有记录模型调用</div>';const cost=data.reported_cost_usd==null?'上游未返回费用':`$${Number(data.reported_cost_usd).toFixed(6)}`;return `<section class="surface-card settings-card" style="margin-top:14px"><div class="section-heading" style="margin:0 0 12px"><div><h3>模型运行观测</h3><p>近 ${Number(data.window_days||30)} 天 · 调用记录保存在本地</p></div><span class="evaluation-status">失败率 ${Number(data.error_rate_pct||0)}%</span></div><div class="evaluation-grid"><div><small>调用 / 失败</small><b>${Number(data.calls||0).toLocaleString('zh-CN')} / ${Number(data.failures||0).toLocaleString('zh-CN')}</b></div><div><small>输入 tokens</small><b>${Number(data.input_tokens||0).toLocaleString('zh-CN')}</b></div><div><small>输出 tokens</small><b>${Number(data.output_tokens||0).toLocaleString('zh-CN')}</b></div><div><small>模型延迟 p50 / p95</small><b>${Number(data.p50_ms||0).toLocaleString('zh-CN')} / ${Number(data.p95_ms||0).toLocaleString('zh-CN')} ms</b></div><div><small>上游报告费用</small><b>${esc(cost)}</b></div><div><small>费用覆盖</small><b>${Number(data.cost_reported_calls||0)} / ${Number(data.calls||0)} 次调用</b></div></div><div style="margin-top:8px">${rows}</div><div class="evaluation-note">费用仅累加模型服务实际返回的费用字段；没有返回费用的调用不会按猜测价格计费。系统不保存提示词、回复正文、密钥或图片。</div></section>`;}
renderView=function(){renderWithMaintenance();if(activeView==='settings'&&settingsSnapshot?.maintenance){$('#app-view')?.insertAdjacentHTML('beforeend',backupSettingsPanel(settingsSnapshot.backupPolicy||{}));$('#app-view')?.insertAdjacentHTML('beforeend',maintenancePanel(settingsSnapshot.maintenance));$('#app-view')?.insertAdjacentHTML('beforeend',modelUsagePanel(settingsSnapshot.metrics?.model_usage||{}));}if(activeView==='settings'&&authMode.enabled&&['owner','admin'].includes(authMode.user?.role)){if(workspaceMembersLoaded){$('#app-view')?.insertAdjacentHTML('beforeend',workspaceMembersPanel());}else if(!workspaceMembersLoading){workspaceMembersLoading=true;api('/api/workspace/members').then(result=>{workspaceMembers=result.members||[];workspaceMembersLoaded=true;renderView();}).catch(error=>toast(`团队成员加载失败：${error.message}`,'error')).finally(()=>{workspaceMembersLoading=false;});}}};

function renderAutomation(){
 const queryList=queries.length?queries.map(q=>`<div class="automation-row"><span class="automation-state">◷</span><div class="automation-copy"><b>${esc(q.name)}</b><p>${esc(q.query)}</p><small>${q.active?'正在追踪':'已暂停'} · ${q.sources.map(s=>SOURCE_NAME[s]||s).join('、')} · 每 ${q.cadence_hours>=168?`${Math.round(q.cadence_hours/168)} 周`:`${q.cadence_hours} 小时`} · 上次 ${q.last_run_at?fmtDate(q.last_run_at,true):'尚未运行'}</small></div><div class="automation-actions"><button class="button" data-run-query="${q.id}">现在同步</button><button class="button" data-toggle-query="${q.id}" data-active="${q.active?0:1}">${q.active?'暂停':'启用'}</button></div></div>`).join(''):emptyState('还没有追踪主题','从一个具体研究问题开始。系统会把新结果放入待确认候选，由你选择后再加入文献库。','<button class="button small primary" data-action="add-query">创建主题检索</button>');
 const runRows=runs.length?runs.map(r=>{const retryable=['failed','partial','interrupted','retryable'].includes(r.status);return `<tr><td>${fmtDate(r.started_at,true)}</td><td>${esc(r.query_name||'研究主题')}</td><td class="log-state ${['failed','partial','interrupted','retryable'].includes(r.status)?'failed':''}">${r.status==='success'?'完成':r.status==='running'?'运行中':r.status==='partial'?'部分失败':r.status==='interrupted'?'已中断':r.status==='retryable'?'等待重试':'失败'}</td><td>${esc(runResultSummary(r))}</td><td><button class="text-link" data-run-detail="${r.id}">查看详情</button>${retryable?` <button class="text-link" data-discovery-history-rerun="${r.id}">重试</button>`:''}</td></tr>`;}).join(''):`<tr><td colspan="5" style="text-align:center;padding:26px;color:#a2aaa4">运行记录会显示在这里</td></tr>`;
 return `${viewHead('RESEARCH AUTOMATION','自动追踪','可检查、可暂停的研究监测。新论文先进入候选队列，确认后才会加入文献库。',`<button class="button primary" data-action="add-query"><span class="plus">＋</span> 创建主题检索</button>`)}<div class="automation-grid"><section class="surface-card automation-card"><div class="section-heading" style="margin:0 0 5px"><div><h3>正在持续观察</h3><p>保存的研究问题和下一次检索频率</p></div></div>${queryList}</section><aside><section class="surface-card automation-card"><div class="section-heading" style="margin:0 0 12px"><div><h3>最近运行</h3><p>候选、确认入库与同步状态</p></div></div><table class="log-table"><tbody>${runRows}</tbody></table></section><div class="agent-banner"><span class="agent-spark">✦</span><div><b>研究 Agent · 当前工作方式</b><p>自动检索、去重并整理候选。摘要助读可选接入兼容 OpenAI 的模型服务；发送前由你确认。AI 的摘要级判断不会伪装成全文证据。</p></div></div><div style="display:flex;gap:7px;margin-top:10px"><button class="button small" data-action="agent-config">模型连接状态</button><button class="button small" data-action="backup">创建完整备份</button></div></aside></div>`;
}

function openModal(html, narrow=false){$('#modal-root').innerHTML=`<div class="modal-backdrop" data-dismiss-modal><section class="modal ${narrow?'narrow':''}" role="dialog" aria-modal="true">${html}</section></div>`;document.body.style.overflow='hidden';const save=$('[data-save-paper]');if(save){const id=save.dataset.savePaper;const body=$('.modal-body');if(body){const section=document.createElement('section');section.className='citation-section';section.innerHTML=`<div class="modal-section-title">引用线索 · OpenAlex</div><p style="font-size:9px;line-height:1.6;color:#89958d">根据该论文的 DOI 查询其参考文献列表。引用关系不代表论文质量或结论正确。</p><div id="citation-list" style="font-size:9px;color:#89958d">正在读取已保存的引用线索…</div><button class="button small" style="margin-top:8px" data-sync-references="${id}">同步参考文献</button>`;body.append(section);loadReferences(id);const map=document.createElement('section');map.className='citation-section';map.innerHTML=`<div class="modal-section-title">研究关联 · 本地画像</div><p style="font-size:9px;line-height:1.6;color:#89958d">把这篇论文放回你的主题和馆藏中判断：高相关、邻近方向和跨领域线索分别展示，结果会随你的反馈更新。</p><div id="connection-list" style="font-size:9px;color:#89958d">正在计算关联…</div><button class="button small" style="margin-top:8px" data-expand-paper="${id}">扩展引用、被引与相似论文</button><div id="expansion-result" style="margin-top:8px"></div>`;body.append(map);loadConnections(id);const evidence=document.createElement('section');evidence.className='citation-section';evidence.innerHTML=`<div class="modal-section-title">原文证据 · 页级文本</div><div id="extraction-panel" class="extraction-panel">正在读取本地 PDF 提取状态…</div>`;body.append(evidence);loadExtraction(id);}}}
function closeModal(){activeModalPaperId='';persistUiState();$('#modal-root').innerHTML='';document.body.style.overflow='';}
function addPaperModal(){openModal(`<div class="modal-head"><div><h3>添加论文到文献库</h3><p>可以手动记录，也可以稍后补齐缺失的元数据。</p></div><button class="close-button" data-close-modal>×</button></div><form id="add-paper-form"><div class="modal-body"><div class="form-grid"><div class="form-field full"><label>论文标题 *</label><input class="field-input" name="title" required placeholder="论文的完整标题"></div><div class="form-field full"><label>作者</label><input class="field-input" name="authors" placeholder="用逗号分隔作者"></div><div class="form-field"><label>年份</label><input class="field-input" name="year" type="number" min="1800" max="2200" placeholder="2026"></div><div class="form-field"><label>会议 / 期刊 / 来源</label><input class="field-input" name="venue" placeholder="NeurIPS、Nature…"></div><div class="form-field"><label>DOI</label><input class="field-input" name="doi" placeholder="10.xxxx/…"></div><div class="form-field"><label>arXiv ID</label><input class="field-input" name="arxiv_id" placeholder="2601.01234"></div><div class="form-field full"><label>摘要</label><textarea class="field-area" name="abstract" placeholder="可稍后再补"></textarea></div><div class="form-field"><label>研究主题</label><input class="field-input" name="topic" placeholder="例如：多模态推理"></div><div class="form-field"><label>标签</label><input class="field-input" name="tags" placeholder="综述, 基准, 精读"></div><div class="form-field full"><label>来源链接</label><input class="field-input" name="url" placeholder="https://…"></div></div></div><div class="modal-foot"><button class="button" type="button" data-close-modal>取消</button><button class="button primary" type="submit">保存到文献库</button></div></form>`,true);}
  function addQueryModal(){openModal(`<div class="modal-head"><div><h3>创建主题检索</h3><p>先用窄主题建立高信噪比提醒，之后可以随时编辑和暂停。</p></div><button class="close-button" data-close-modal>×</button></div><form id="add-query-form"><div class="modal-body"><div class="form-grid"><div class="form-field full"><label>主题名称</label><input class="field-input" name="name" placeholder="例如：长视频理解与时序推理"></div><div class="form-field full"><label>检索问题 / 关键词 *</label><textarea class="field-area" name="query" required placeholder="multimodal reasoning · 可用英文关键词提升覆盖"></textarea><span class="form-help">系统会生成查询计划，跨源检索、去重并保留来源健康记录。</span></div><div class="form-field full"><label>数据来源</label><div style="display:flex;gap:16px;flex-wrap:wrap"><label class="check-label"><input type="checkbox" name="source" value="arxiv" checked> arXiv</label><label class="check-label"><input type="checkbox" name="source" value="openalex" checked> OpenAlex</label><label class="check-label"><input type="checkbox" name="source" value="crossref"> Crossref</label><label class="check-label"><input type="checkbox" name="source" value="europepmc"> Europe PMC</label><label class="check-label"><input type="checkbox" name="source" value="semanticscholar"> Semantic Scholar</label></div><span class="form-help">Europe PMC 适合医学/生命科学；Semantic Scholar 提供语义覆盖但可能受公开配额限制。</span></div><div class="form-field full"><label>长期过滤条件（可选）</label><div class="search-advanced"><input class="field-input" name="author" placeholder="作者"><input class="field-input" name="venue" placeholder="期刊 / 会议"><input class="field-input" name="year_from" type="number" min="1800" max="2200" placeholder="起始年份"><input class="field-input" name="year_to" type="number" min="1800" max="2200" placeholder="结束年份"><select class="field-select" name="work_type"><option value="">全部类型</option><option value="journal">期刊</option><option value="conference">会议</option><option value="review">综述</option><option value="preprint">预印本</option></select><select class="field-select" name="sort"><option value="relevance">相关性优先</option><option value="newest">最新优先</option><option value="oldest">最早优先</option></select></div></div><div class="form-field"><label>检查频率</label><select class="field-select" name="cadence"><option value="168">每周</option><option value="72">每 3 天</option><option value="24">每天</option><option value="336">每两周</option></select></div><div class="form-field"><label>入库策略</label><select class="field-select" disabled><option>自动去重后进入新发现</option></select><span class="form-help">自动只做元数据入库，不改写你的笔记或阅读状态。</span></div></div></div><div class="modal-foot"><button class="button" type="button" data-close-modal>取消</button><button class="button primary" type="submit">保存并开始追踪</button></div></form>`,true);}

// The saved-topic form mirrors the ad-hoc discovery controls so long-running
// searches keep the same expansion and non-repetition policy.
function addQueryModal(){openModal(`<div class="modal-head"><div><h3>创建主题检索</h3><p>保存后按频率自动追踪，系统会记住反馈并压低重复结果。</p></div><button class="close-button" data-close-modal>×</button></div><form id="add-query-form"><div class="modal-body"><div class="form-grid"><div class="form-field full"><label>主题名称</label><input class="field-input" name="name" placeholder="例如：长视频理解与时序推理"></div><div class="form-field full"><label>检索问题 / 关键词 *</label><textarea class="field-area" name="query" required placeholder="multimodal reasoning 或 多模态推理"></textarea></div><div class="form-field full"><label>数据来源</label><div style="display:flex;gap:14px;flex-wrap:wrap"><label class="check-label"><input type="checkbox" name="source" value="arxiv" checked> arXiv</label><label class="check-label"><input type="checkbox" name="source" value="openalex" checked> OpenAlex</label><label class="check-label"><input type="checkbox" name="source" value="crossref"> Crossref</label><label class="check-label"><input type="checkbox" name="source" value="europepmc"> Europe PMC</label><label class="check-label"><input type="checkbox" name="source" value="semanticscholar"> Semantic Scholar</label><label class="check-label"><input type="checkbox" name="source" value="dblp" checked> DBLP</label></div></div><div class="form-field full"><label>长期发现策略</label><div class="search-advanced"><select class="field-select" name="search_depth"><option value="focused">精准检索</option><option value="balanced" selected>平衡检索</option><option value="deep">深度检索（综述/基准/实证）</option></select><select class="field-select" name="discovery_mode"><option value="balanced" selected>平衡发现</option><option value="latest">前沿优先</option><option value="foundations">经典/高影响优先</option><option value="explore">邻域探索</option></select><select class="field-select" name="sort"><option value="relevance">综合相关性</option><option value="newest">最新优先</option><option value="novelty">新发现优先</option><option value="foundations">经典/高影响优先</option></select><select class="field-select" name="work_type"><option value="">全部类型</option><option value="journal">期刊</option><option value="conference">会议</option><option value="review">综述</option><option value="preprint">预印本</option></select><input class="field-input" name="author" placeholder="作者（可选）"><input class="field-input" name="venue" placeholder="会议/期刊（可选）"><input class="field-input" name="exclude_terms" placeholder="排除词，用逗号分隔"><input class="field-input" name="year_from" type="number" min="1800" max="2200" placeholder="起始年份"><input class="field-input" name="year_to" type="number" min="1800" max="2200" placeholder="结束年份"></div></div><div class="search-options"><label class="check-label"><input type="checkbox" name="expand_concepts" checked> 概念扩展</label><label class="check-label"><input type="checkbox" name="expand_relations"> 沿馆藏邻域扩展</label><label class="check-label"><input type="checkbox" name="suppress_seen"> 只保留新发现</label></div><div class="form-field"><label>检查频率</label><select class="field-select" name="cadence"><option value="168">每周</option><option value="72">每 3 天</option><option value="24">每天</option><option value="336">每两周</option></select></div></div></div><div class="modal-foot"><button class="button" type="button" data-close-modal>取消</button><button class="button primary" type="submit">保存并开始追踪</button></div></form>`,true);}

// DBLP is useful for CS conference coverage but some networks challenge its
// public endpoint. Keep it opt-in by default while leaving the connector
// available for users whose network can reach it.
const _addQueryModal = addQueryModal;
addQueryModal = function(){_addQueryModal();const dblp=$('#modal-root input[name="source"][value="dblp"]');if(dblp){dblp.checked=false;const label=document.createElement('label');label.className='check-label';label.innerHTML='<input type="checkbox" name="source" value="openreview"> OpenReview';dblp.closest('label')?.after(label);}};
const _addQueryModalReviewOnly=addQueryModal;
addQueryModal=function(){_addQueryModalReviewOnly();const fields=$$('#add-query-form .form-field');const strategy=fields.find(field=>field.textContent.includes('自动去重后进入新发现'));const copy='<label>发现与入库</label><p class="form-help">自动追踪只保存新候选，不会直接写入文献库。你可以在“发现论文”里查看结果并选择导入。</p>';if(strategy)strategy.innerHTML=copy;else $('#add-query-form .form-grid')?.insertAdjacentHTML('beforeend',`<div class="form-field full">${copy}</div>`);};
const _addQueryModalWithTavily=addQueryModal;
addQueryModal=function(){_addQueryModalWithTavily();const group=$$('#add-query-form .form-field').find(field=>field.querySelector('input[name="source"]'));if(!group||group.querySelector('input[name="source"][value="tavily"]'))return;const openreview=group.querySelector('input[name="source"][value="openreview"]')?.closest('label');if(!openreview)return;const label=document.createElement('label');label.className='check-label';label.innerHTML='<input type="checkbox" name="source" value="tavily"> Tavily 联网发现';openreview.after(label);const note=document.createElement('small');note.className='form-help';note.textContent='可选来源，需要本地配置 Tavily Key；启用后定期同步会调用它，未核验网页只作候选，不会自动入库。';group.append(note);};

const _agentGoalFormWithTavily=agentGoalForm;
agentGoalForm=function(){const html=_agentGoalFormWithTavily();const openreview='<label class="check-label"><input type="checkbox" name="source" value="openreview"> OpenReview</label>';const tavily='<label class="check-label"><input type="checkbox" name="source" value="tavily"> Tavily 联网发现</label><small class="form-help">可选来源，需要本地配置 Tavily Key；网页候选核验前仅作线索，定期追踪会按设置频率调用。</small>';return html.replace(openreview,openreview+tavily);};

